void pet_dma_in(void) {
  int error;

  unsigned int dma_occupancy;

  CSR_READ(DMA_0_SCHEDULE_OCCUPANCY, dma_occupancy);  // switch to dma_occupancy

  if(dma_occupancy == 0) {

    // Check current process for available space
    if (dma_state == 0){
      if (dma_a_empty == 0){
        return;
      }
      dma_a_empty = 0; // hold a
    }

    if (dma_state == 1){
      if (dma_b_empty == 0){
        return;
      }
      dma_b_empty = 0; // hold b
    } 

    dma_state = (dma_state+1)&0x1;
    // Do something with the data   
    trig_dma_in(dma_state, 0xffffffff);
  }

}

unsigned int enable_check_subcarrier = 0;

void check_subcarrier(unsigned int* data) {
    uint64_t real;
    uint64_t imag;
    // float real;
    // float imag;

    const unsigned int sc = 1022;

    unsigned int mem = data[sc];

    real = (int16_t)(mem & 0xffff);
    imag = (int16_t)(mem>>16 & 0xffff);

    // real = int_real;
    // imag = int_imag;

    uint64_t mag2 = (real*real) + (imag*imag);

    const uint64_t tol = (0x1f00*0x1f00);

    if( mag2 < tol ) {
        ring_block_send_eth(CS10_MAG_CHECK_PCCMD | 0x00000 | ((uint32_t)(real&0xffff)) );
        ring_block_send_eth(CS10_MAG_CHECK_PCCMD | 0x10000 | ((uint32_t)(imag&0xffff)) );
    }
}


